def compute(vars):
    total_shares = vars["v1"] + vars["v2"] + vars["v3"]
    return {
        "value": total_shares,
        "trace": {
            "total_shares": total_shares,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "shares"
            }
        }
    }
